import{_ as o,o as l,c as r,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Ceph Developer Summit Quincy: Crimson","description":"","frontmatter":{"title":"Ceph Developer Summit Quincy: Crimson","date":"2021-04-08T00:00:00.000Z","updated":"2021-04-08T00:00:00.000Z","tags":["Ceph","Distributed Storage","CephFS","BlueStore","Crimson"],"categories":["会议纪要","技术讨论"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Developer_Summit_Quincy_-_Crimson.md","filePath":"posts/2021/Ceph_Developer_Summit_Quincy_-_Crimson.md","lastUpdated":1780459816000}'),e={name:"posts/2021/Ceph_Developer_Summit_Quincy_-_Crimson.md"};function a(n,i,s,p,u,c){return l(),r("div",null,[...i[0]||(i[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主题一-适应ceph的boost-asio代码到c-star-reactor" tabindex="-1">主题一：适应Ceph的Boost ASIO代码到C-Star Reactor <a class="header-anchor" href="#主题一-适应ceph的boost-asio代码到c-star-reactor" aria-label="Permalink to &quot;主题一：适应Ceph的Boost ASIO代码到C-Star Reactor&quot;">​</a></h4><ul><li><p><strong>讨论内容</strong>：</p><ul><li>讨论如何将现有依赖Boost ASIO的代码适配到C-Star Reactor中。</li><li>探讨是否可以通过包装和适当的回调函数直接在Reactor中运行。</li><li>初步认为需要进一步调查是否需要进行此项工作，特别是对于实时RBD（Live RBD）。</li></ul></li><li><p><strong>决定事项</strong>：</p><ul><li>需要进一步调查和评估将Boost ASIO代码适配到C-Star Reactor的可行性和必要性。</li><li>可能需要一个初始原型来验证代码的适配情况。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>由熟悉Boost ASIO和C-Star的开发人员进行深入调查和原型开发。</li></ul></li></ul><h4 id="主题二-rapid-car-diamond和rapid-car-monitor设计" tabindex="-1">主题二：Rapid CAR Diamond和Rapid CAR Monitor设计 <a class="header-anchor" href="#主题二-rapid-car-diamond和rapid-car-monitor设计" aria-label="Permalink to &quot;主题二：Rapid CAR Diamond和Rapid CAR Monitor设计&quot;">​</a></h4><ul><li><p><strong>讨论内容</strong>：</p><ul><li>讨论了如何设计Replica Daemon和Rapid CAR Monitor来管理复制信息。</li><li>现有设计涉及在Replica Monitor中维护Replica Daemon的信息，包括RDMA的IP地址和端口等。</li></ul></li><li><p><strong>决定事项</strong>：</p><ul><li>需要重新考虑是否需要在Monitor中维护这些信息，可能通过RADOS对象和watch/notify机制来实现更为合适。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>重新评估和设计Replica Daemon和Rapid CAR Monitor的管理机制，避免对Monitor的过度依赖。</li><li>向社区征求反馈和建议，进一步优化设计。</li></ul></li></ul><h4 id="主题三-crimson的多核支持与m2n映射" tabindex="-1">主题三：Crimson的多核支持与M2N映射 <a class="header-anchor" href="#主题三-crimson的多核支持与m2n映射" aria-label="Permalink to &quot;主题三：Crimson的多核支持与M2N映射&quot;">​</a></h4><ul><li><p><strong>讨论内容</strong>：</p><ul><li>讨论了如何在Crimson中实现多核支持，包括处理客户端连接、PG状态和后端存储实现。</li><li>探讨了是否需要在Messenger中实现多核支持，以及如何处理跨核通信。</li></ul></li><li><p><strong>决定事项</strong>：</p><ul><li>决定先实现PG在多个核心上的分布，再考虑Messenger和C-Store的多核支持。</li><li>需要实现一个跨核服务来管理PG到核心的映射。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>开发跨核服务，实现PG到核心的映射。</li><li>逐步实现Messenger和C-Store的多核支持。</li></ul></li></ul><h4 id="主题四-c-store的当前状态和未来工作" tabindex="-1">主题四：C-Store的当前状态和未来工作 <a class="header-anchor" href="#主题四-c-store的当前状态和未来工作" aria-label="Permalink to &quot;主题四：C-Store的当前状态和未来工作&quot;">​</a></h4><ul><li><p><strong>讨论内容</strong>：</p><ul><li>回顾了C-Store的当前进展，包括事务层、逻辑块映射、OMAP和垃圾回收等。</li><li>讨论了如何支持ZNS设备和其他可变存储设备。</li></ul></li><li><p><strong>决定事项</strong>：</p><ul><li>需要进一步的工作来优化C-Store的性能和稳定性，包括引入更多的性能指标和调试工具。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>引入性能指标和调试工具，优化C-Store的性能和稳定性。</li><li>探索和支持新的存储设备，如ZNS和持久内存。</li></ul></li></ul><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><p>本次会议涵盖了多个关键议题，包括Boost ASIO代码的适配、Rapid CAR Monitor的设计、Crimson的多核支持和C-Store的优化。每个议题都有明确的后续行动计划，旨在推动Ceph的进一步发展和优化。</p>',11)])])}const h=o(e,[["render",a]]);export{m as __pageData,h as default};
